function classificaCup(d,fino) {
  var teams={},nomi=Object.create(null);
  function row(gr,name){var k=gr+'|'+name;if(!teams[k])teams[k]={gir:gr,n:name,pt:0,v:0,p:0,s:0,gf:0,gs:0,fp:0};return teams[k];}
